<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/app.php';
require_once __DIR__ . '/../includes/referral_opportunities.php';
require_once __DIR__ . '/../includes/customer_referrals.php';

$user = require_login('REFERRER');
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0;
$referral = referrer_referral($id, (int) $user['id']);
if (!$referral) { set_flash('danger', 'That referral was not found.'); redirect('referrer/referrals.php'); }
ActivityLogService::logActivity((int) $user['id'], 'REFERRER', 'Referral', 'Referral Viewed', 'Referral', (int) $referral['id'], 'Viewed referral details.');
$history = referral_history((int) $referral['id']);
$pageTitle = 'Referral #' . $referral['id'] . ' | ' . APP_NAME; require_once __DIR__ . '/../includes/header.php';
?>
<main class="opportunity-page"><div class="container py-5"><div class="opportunity-hero"><div><span class="eyebrow"><i class="bi bi-person-check"></i> Referral #<?= (int) $referral['id'] ?></span><h1><?= e($referral['customer_name']) ?></h1><p><?= e($referral['opportunity_title']) ?> · <?= e($referral['business_name'] ?: 'Business') ?></p></div><a class="btn btn-light border" href="<?= e(url('referrer/referrals.php')) ?>">Back to my referrals</a></div><div class="row g-4 mt-1"><div class="col-lg-8"><section class="detail-card mb-4"><h2>Customer details</h2><dl class="detail-list"><div><dt>Name</dt><dd><?= e($referral['customer_name']) ?></dd></div><div><dt>Phone</dt><dd><?= e($referral['customer_phone']) ?></dd></div><div><dt>Email</dt><dd><?= e($referral['customer_email'] ?: 'Not provided') ?></dd></div><div><dt>Address</dt><dd><?= e($referral['customer_address']) ?>, <?= e($referral['customer_city']) ?>, <?= e($referral['customer_state']) ?></dd></div><div><dt>Remarks</dt><dd><?= nl2br(e($referral['customer_notes'] ?: 'None provided')) ?></dd></div></dl></section><section class="detail-card"><h2>Business and campaign</h2><dl class="detail-list"><div><dt>Business</dt><dd><?= e($referral['business_name'] ?: 'Business') ?></dd></div><div><dt>Campaign</dt><dd><?= e($referral['opportunity_title']) ?></dd></div><div><dt>Selected product</dt><dd><?= e($referral['product_name'] ?: 'Legacy referral') ?></dd></div><div><dt>Commission rate</dt><dd><?= $referral['commission_percentage'] !== null ? e($referral['commission_percentage']) . '%' : 'Fixed legacy reward' ?></dd></div></dl></section></div><div class="col-lg-4"><section class="detail-card mb-4"><h2>Commission and status</h2><dl class="detail-list"><div><dt>Sale amount</dt><dd><?= $referral['sale_amount'] !== null ? e(opportunity_money($referral['sale_amount'])) : 'Pending completion' ?></dd></div><div><dt>Gross Commission</dt><dd><?= $referral['calculated_commission'] !== null ? e(opportunity_money($referral['calculated_commission'])) : 'Pending completion' ?></dd></div><?php if ($referral['status'] === 'Completed'): ?><div><dt>Platform Fee (2%)</dt><dd><?= e(opportunity_money($referral['platform_fee'] ?? 0)) ?></dd></div><div><dt>Net Reward Credited</dt><dd><?= e(opportunity_money($referral['net_commission'] ?? $referral['calculated_commission'])) ?></dd></div><?php endif; ?><div><dt>Current status</dt><dd><span class="role-badge"><?= e($referral['status']) ?></span></dd></div></dl></section><section class="detail-card"><h2>Referral History</h2><?php foreach ($history as $item): ?><div class="d-flex gap-3 mb-3"><i class="bi bi-check-circle-fill text-success fs-5"></i><div><strong class="d-block text-dark"><?= e($item['status']) ?></strong><small><?= e(date('d M Y, h:i A', strtotime($item['created_at']))) ?><?= $item['note'] ? ' · ' . e($item['note']) : '' ?></small></div></div><?php endforeach; if (!$history): ?><p class="mb-0 text-muted">Submitted <?= e(date('d M Y, h:i A', strtotime($referral['submitted_at']))) ?></p><?php endif; ?></section></div></div></div></main>
